solutions.naive:
class Solution:
    def numSquares(self, n: int) -> int:
        squares = [i * i for i in range(1, int(n ** 0.5) + 1)]

        def dfs(rem: int) -> int:
            if rem == 0:
                return 0
            return 1 + min(dfs(rem - sq) for sq in squares if sq <= rem)

        return dfs(n)

