class Solution:
    def numSquares(self, n: int) -> int:
        squares = [i * i for i in range(1, int(n ** 0.5) + 1)]
        memo = {0: 0}

        def dfs(rem: int) -> int:
            if rem not in memo:
                memo[rem] = 1 + min(dfs(rem - sq) for sq in squares if sq <= rem)
            return memo[rem]

        return dfs(n)

