class Solution:
    def numSquares(self, n: int) -> int:
        squares = [i * i for i in range(1, int(n ** 0.5) + 1)]
        dp = [0] + [float("inf")] * n
        for total in range(1, n + 1):
            for sq in squares:
                if sq > total:
                    break
                dp[total] = min(dp[total], 1 + dp[total - sq])
        return dp[n]

